function shuffle(values) {
    for (let i = values.length - 1; i > 0; i -= 1) {
        const j = randInt(0, i);
        [values[i], values[j]] = [values[j], values[i]];
    }
    return values;
}

function randomSyllableName() {
    const parts = randInt(2, 3);
    let name = "";
    for (let i = 0; i < parts; i += 1) name += pick(SYLLABLES);
    if (chance(45)) name += String(randInt(1, 99));
    return name;
}

function localUsername() {
    if (chance(18)) return pick(FIRST_NAMES);
    if (chance(22)) return `${pick(FIRST_NAMES)}${randInt(1, 99)}`;
    if (chance(18)) return `${pick(FIRST_NAMES)}_${pick(WORDS)}`;
    if (chance(12)) return `${pick(ADJECTIVES)}${titleCase(pick(WORDS))}`;
    if (chance(10)) return `${pick(FIRST_NAMES)}${pick(COUNTRY)}`;
    if (chance(8)) return `${pick(WORDS)}${randInt(10, 999)}`;
    if (chance(6)) return `${pick(TRANSLIT)}${randInt(1, 99)}`;
    if (chance(4)) return randomSyllableName();
    return `${pick(WORDS)}${chance(50) ? "_" : ""}${pick(WORDS)}`.slice(0, 24);
}

function nameTokens(name) {
    return name
        .replace(/([a-z])([A-Z])/g, "$1 $2")
        .split(/[._\-\s]+/)
        .map((token) => token.toLowerCase())
        .filter(Boolean);
}

function qualityScore(name) {
    const lower = name.toLowerCase();
    let score = 0;
    if (FIRST_NAMES.includes(lower)) score += 3;
    if (WORDS.includes(lower)) score += 2;
    if (/^[A-Z]?[a-z]{3,}$/.test(name)) score += 2;
    if (/^[A-Z][a-z]+[A-Z][a-z]+$/.test(name)) score += 2;
    if (/^[a-z]+[._-][a-z]+$/i.test(name)) score += 1;
    if (/\d{1,3}$/.test(name)) score += 1;
    if (/^[a-z]{2}[._-]?[a-z]{2}\d{2,}$/i.test(name)) score -= 5;
    if (/^\d/.test(name)) score -= 4;
    if (/(.)\1{3,}/i.test(name)) score -= 2;
    if (lower.length < 3) score -= 2;
    return score;
}

function normalizeUsername(value) {
    if (typeof value !== "string") return null;
    const name = value.trim().replace(/^[@#]+/, "");
    if (!USERNAME_RE.test(name)) return null;
    if (/^[._-]|[._-]$/.test(name)) return null;
    if (/[._-]{2,}/.test(name)) return null;
    if ((name.match(/[._-]/g) || []).length > 1) return null;
    if (/[._-]\d{3,}$/.test(name)) return null;
    if (!/[A-Za-z]{2}/.test(name)) return null;
    if (/\d{5,}/.test(name)) return null;
    if (/^\d/.test(name)) return null;
    // Small models love "AdjectiveNoun12" gamer tags and shouty all-caps
    // names. Keep a few of the former, but reject the latter outright.
    if (/^[A-Z][a-z]+[A-Z][a-z]+\d{1,2}$/.test(name)) return null;
    if (/^[A-Z0-9._-]+$/.test(name) && /[A-Z]{2}/.test(name)) return null;
    if (RESERVED_RE.test(name) || BOT_RE.test(name)) return null;
    if (REFERENCE_AVOID.has(name.toLowerCase())) return null;
    if (nameTokens(name).some((token) => BLOCKED_TOKENS.has(token))) return null;
    if (qualityScore(name) < -1) return null;
    return name;
}

function makeDisplayName(username) {
    const cleaned = username
        .replace(/[._-]+/g, " ")
        .replace(/([a-z])([A-Z])/g, "$1 $2")
        .trim();
    const roll = randInt(0, 99);
    let name;
    if (roll < 22) {
        name = `${titleCase(pick(FIRST_NAMES))} ${titleCase(pick(LAST_NAMES))}`;
    } else if (roll < 42) {
        name = titleCase(pick(FIRST_NAMES));
    } else if (roll < 64) {
        name = cleaned.length >= 2 ? cleaned : titleCase(username);
    } else if (roll < 82) {
        name = `${titleCase(pick(ADJECTIVES))} ${titleCase(pick(WORDS))}`;
    } else {
        name = titleCase(cleaned || username);
    }
    return name.slice(0, 32);
}

function makeBio(username) {
    // Deterministic-ish so repeated previews do not look random for the same
    // name, without making every account share one of five obvious phrases.
    let hash = 0;
    for (const char of username) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
    return BIOS[hash % BIOS.length];
}

function makeStatus(username) {
    let hash = 7;
    for (const char of username) hash = (hash * 17 + char.charCodeAt(0)) >>> 0;
    return STATUSES[hash % STATUSES.length];
}

function randomPassword() {
    return `Nc-${crypto.randomBytes(18).toString("base64url")}!${randInt(10, 99)}`;
}

function randomEmail(index) {
    const stamp = Date.now().toString(36);
    const noise = crypto.randomBytes(5).toString("hex");
    return `seed${stamp}${index}${noise}@seed.nullcord.test`;
}

function safeWriteJson(file, value, mode = 0o600) {
    fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
    const temporary = `${file}.${process.pid}.tmp`;
    fs.writeFileSync(temporary, `${JSON.stringify(value, null, 2)}\n`, { mode });
    fs.renameSync(temporary, file);
    try {
        fs.chmodSync(file, mode);
    } catch {
        // best effort on filesystems without chmod
    }
}

class StyleMemory {
    constructor() {
        this.patterns = [];
        this.fragments = [];
        this.recent = [];
        this.load();
    }

    load() {
        try {
            const raw = JSON.parse(fs.readFileSync(MEMORY_FILE, "utf8"));
            this.patterns = Array.isArray(raw.patterns) ? raw.patterns.filter((x) => typeof x === "string") : [];
            this.fragments = Array.isArray(raw.fragments) ? raw.fragments.filter((x) => typeof x === "string") : [];
            this.recent = Array.isArray(raw.recent) ? raw.recent.filter((x) => typeof x === "string") : [];
        } catch {
            // first run
        }
    }

    remember(names, patterns = [], fragments = []) {
        const pushUnique = (target, values, limit) => {
            for (const value of values) {
                if (typeof value !== "string") continue;
                const clean = value.trim().slice(0, 160);
                if (!clean) continue;
                target.push(clean);
            }
            return [...new Set(target)].slice(-limit);
        };
        this.recent = pushUnique(this.recent, names, 2000);
        this.patterns = pushUnique(this.patterns, patterns, 40);
        this.fragments = pushUnique(this.fragments, fragments, 120);
        this.save();
    }

    save() {
        safeWriteJson(MEMORY_FILE, {
            updatedAt: new Date().toISOString(),
            patterns: this.patterns,
            fragments: this.fragments,
            recent: this.recent,
        });
    }
}

function parseJsonLoose(text) {
    if (typeof text !== "string") return null;
    const cleaned = text
        .trim()
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/, "")
        .trim();
    try {
        return JSON.parse(cleaned);
    } catch {
        const start = cleaned.indexOf("{");
        const end = cleaned.lastIndexOf("}");
        if (start >= 0 && end > start) {
            try {
                return JSON.parse(cleaned.slice(start, end + 1));
            } catch {
                return null;
            }
        }
        return null;
    }
}

class NameForge {
    constructor(options, memory) {
        this.options = options;
        this.memory = memory;
        this.model = options.model;
        this.aiAvailable = !options.noAi;
        this.consecutiveFailures = 0;
        this.styleCursor = crypto.randomInt(0, AI_STYLES.length);
    }

    async warmup() {
        if (!this.aiAvailable) return;
        try {
            const response = await fetch(`${this.options.ollama}/api/tags`, {
                signal: AbortSignal.timeout(5000),
            });
            if (!response.ok) throw new Error(`Ollama returned ${response.status}`);
            const data = await response.json();
            const models = (data.models || []).map((entry) => entry.name);
            if (!models.length) throw new Error("Ollama has no models installed");
            if (models.includes(this.model)) return;
            const preferred = [
                this.model,
                "qwen2.5:3b",
                "qwen2.5:7b",
                "qwen2.5:14b",
                "qwen3:8b",
                "llama3.2:3b",
                "mistral:7b",
                "smollm:1.7b",
            ];
            const found = preferred.find((name) => models.includes(name));
            if (found) {
                console.log(`[ai] ${this.model} not installed; using ${found}`);
                this.model = found;
            } else {
                console.log(`[ai] ${this.model} not installed; using ${models[0]}`);
                this.model = models[0];
            }
        } catch (error) {
            this.aiAvailable = false;
            console.log(`[ai] offline (${error.message}); using local generator`);
        }
    }

    async ollama(prompt, { numPredict = 1000, temperature = 1.0, timeout = 90000 } = {}) {
        const response = await fetch(`${this.options.ollama}/api/generate`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                model: this.model,
                prompt,
                stream: false,
                format: "json",
                keep_alive: "10m",
                options: {
                    temperature,
                    top_p: 0.95,
                    repeat_penalty: 1.08,
                    num_predict: numPredict,
                },
            }),
            signal: AbortSignal.timeout(timeout),
        });
        if (!response.ok) {
            const text = await response.text();
            throw new Error(`Ollama ${response.status}: ${text.slice(0, 160)}`);
        }
        const data = await response.json();
        return data.response || data.message?.content || "";
    }

    async aiNames(count, seen) {
        const learnedPatterns = this.memory.patterns.slice(-8).join("; ");
        const learnedFragments = this.memory.fragments.slice(-28).join(", ");
        const avoid = [...new Set([...this.memory.recent.slice(-70), ...seen.slice(-30)])]
            .map((name) => name.toLowerCase())
            .join(", ");
        const style = AI_STYLES[this.styleCursor % AI_STYLES.length];
        const secondStyle = AI_STYLES[(this.styleCursor + 3) % AI_STYLES.length];
        this.styleCursor += 1;
        const prompt = [
            "You invent convincing chat usernames for a small Discord-like site.",
            `Create exactly ${count} NEW, unique handles for ordinary people, not celebrities.`,
            `This batch should mostly be ${style}.`,
            `A few may also be ${secondStyle}.`,
            "Make them feel hand-picked and varied; do not repeat the same base words.",
            "Rules: 2-24 characters; ASCII letters, digits, dot, underscore, hyphen only;",
            "no spaces; no trailing separators; no 5+ digit runs; most names 3-14 chars;",
            "do not use game, brand, anime, film or fictional-character names;",
            "do not use bot, admin, mod, support, official or staff terms;",
            "do not use initials followed by numbers; avoid generic adjective+noun pairs.",
            learnedPatterns ? `Learned style patterns to use sparingly: ${learnedPatterns}` : "",
            learnedFragments ? `Fresh fragments learned earlier: ${learnedFragments}` : "",
            avoid ? `Do not reuse any of these names: ${avoid}` : "",
            'Return strict JSON only: {"usernames":["...","..."]}. No commentary.',
        ]
            .filter(Boolean)
            .join("\n");
        let lastError;
        for (let attempt = 0; attempt < 2; attempt += 1) {
            try {
                const raw = await this.ollama(prompt, {
                    numPredict: Math.min(1800, 220 + count * 35),
                    temperature: 0.95 + attempt * 0.1,
                });
                const parsed = parseJsonLoose(raw);
                const values = Array.isArray(parsed) ? parsed : parsed?.usernames;
                if (Array.isArray(values)) {
                    this.consecutiveFailures = 0;
                    if (this.options.verbose) {
                        console.log(`[ai] raw (${values.length}): ${values.slice(0, 12).join(", ")}`);
                    }
                    return values;
                }
                lastError = new Error("model did not return a usernames array");
            } catch (error) {
                lastError = error;
            }
        }
        if (this.options.verbose) console.log(`[ai] batch failed: ${lastError?.message || "unknown"}`);
        this.consecutiveFailures += 1;
        if (this.consecutiveFailures >= 3) {
            this.aiAvailable = false;
            console.log(`[ai] disabling model after repeated failures (${lastError.message}); using local generator`);
        }
        return [];
    }

    async reflect(names) {
        if (!this.aiAvailable || names.length < 3) return;
        const prompt = [
            "Look at these accepted chat usernames:",
            names.join(", "),
            "Extract reusable style knowledge. Do not repeat the full usernames.",
            'Return strict JSON: {"patterns":["short abstract style rules"],"fragments":["fresh short word fragments"]}.',
            "Give 4 patterns and 8 fragments. Patterns should describe structure, casing, rhythm or origin.",
        ].join("\n");
        try {
            const raw = await this.ollama(prompt, { numPredict: 500, temperature: 0.7, timeout: 60000 });
            const parsed = parseJsonLoose(raw);
            if (parsed) {
                const patterns = (Array.isArray(parsed.patterns) ? parsed.patterns : [])
                    .filter(
                        (value) =>
                            typeof value === "string" &&
                            !/[{}]/.test(value) &&
                            !/\b(use|prefix|suffix|template|placeholder)\b/i.test(value),
                    );
                const fragments = (Array.isArray(parsed.fragments) ? parsed.fragments : [])
                    .filter((value) => typeof value === "string" && /^[A-Za-z]{2,12}$/.test(value));
                this.memory.remember(names, patterns, fragments);
            }
        } catch {
            // Reflection is an enhancement; never block account creation on it.
        }
    }

    async generate(count, existing = []) {
        const accepted = [];
        const seen = new Set(existing.map((name) => name.toLowerCase()));
        let rounds = 0;
        while (accepted.length < count && rounds < Math.max(20, count * 6)) {
            rounds += 1;
            const need = Math.min(36, Math.max(8, Math.ceil((count - accepted.length) * 1.5)));
            let raw = [];
            if (this.aiAvailable) {
                raw = await this.aiNames(need, [...seen]);
            }
            const aiCandidates = new Set(
                raw
                    .filter((value) => typeof value === "string")
                    .map((value) => value.trim().toLowerCase()),
            );
            raw.push(...Array.from({ length: Math.max(8, need) }, localUsername));
            const fresh = [];
            const freshAi = [];
            const aiQuota = Math.ceil(need * 0.34);
            let aiUsed = 0;
            for (const value of raw) {
                const name = normalizeUsername(value);
                if (!name) continue;
                const key = name.toLowerCase();
                if (seen.has(key)) continue;
                const fromAi = aiCandidates.has(key);
                if (fromAi && aiUsed >= aiQuota) continue;
                seen.add(key);
                accepted.push(name);
                fresh.push(name);
                if (fromAi) {
                    aiUsed += 1;
                    freshAi.push(name);
                }
                if (accepted.length >= count) break;
            }
            if (fresh.length) {
                this.memory.remember(fresh);
                // Reflection is only useful when it is learning from model
                // output. Feeding local fallback names back in makes small
                // models collapse into initials+digits loops.
                await this.reflect(freshAi);
            } else {
                // Guarantee progress even if the model produces only duplicates.
                for (let i = 0; i < 8 && accepted.length < count; i += 1) {
                    const name = normalizeUsername(localUsername());
                    if (!name || seen.has(name.toLowerCase())) continue;
                    seen.add(name.toLowerCase());
                    accepted.push(name);
                }
            }
        }
        return shuffle(accepted.slice(0, count));
    }
}

class ApiError extends Error {
    constructor(status, body, pathName) {
        const type = body && typeof body === "object" ? body.type || body.error || "" : "";
        super(`${pathName} -> HTTP ${status}${type ? ` (${type})` : ""}`);
        this.status = status;
        this.type = type;
        this.body = body;
    }
}

class Api {
    constructor(baseUrl) {
        this.baseUrl = baseUrl.replace(/\/+$/, "");
        this.authWindow = [];
        this.generalWindow = [];
    }

    async gate(window, limit) {
        while (true) {
            const now = Date.now();
            while (window.length && now - window[0] > 10500) window.shift();
            if (window.length < limit) {
                window.push(now);
                return;
            }
            const wait = 10600 - (now - window[0]);
            await sleep(Math.max(50, wait));
        }
    }

    async authSlot() {
        // The backend allows 15 auth requests per 10 seconds. Account creation
        // plus login is two, so stay under the limit with a small buffer.
        await this.gate(this.authWindow, 13);
    }

    async generalSlot() {
        await this.gate(this.generalWindow, 16);
    }

    async request(pathName, { method = "GET", body, token, retries = 4 } = {}) {
        let lastError;
        for (let attempt = 0; attempt < retries; attempt += 1) {
            try {
                const response = await fetch(`${this.baseUrl}${pathName}`, {
                    method,
                    headers: {
                        "Content-Type": "application/json",
                        ...(token ? { "x-session-token": token } : {}),
                    },
                    body: body === undefined ? undefined : JSON.stringify(body),
                    signal: AbortSignal.timeout(45000),
                });
                const text = await response.text();
                let data = null;
                if (text) {
                    try {
                        data = JSON.parse(text);
                    } catch {
                        data = text;
                    }
                }
                if (response.status === 429) {
                    const retryAfter = Number(response.headers.get("retry-after")) || 5;
                    await sleep(retryAfter * 1000 + randInt(100, 500));
                    continue;
                }
                if (response.status >= 500 && attempt + 1 < retries) {
                    await sleep(1000 * (attempt + 1));
                    continue;
                }
                if (!response.ok) throw new ApiError(response.status, data, pathName);
                return data;
            } catch (error) {
                if (error instanceof ApiError) throw error;
                lastError = error;
                if (attempt + 1 < retries) {
                    await sleep(700 * (attempt + 1));
                    continue;
                }
            }
        }
        throw lastError || new Error(`${pathName} failed`);
    }

    async health() {
        await this.generalSlot();
        const data = await this.request("/");
        if (!data?.stoat && !data?.revolt) {
            throw new Error("the API responded, but it does not look like a Stoat/Revolt server");
        }
        return data;
    }
}

function readPublicUrls() {
    const values = {};
    try {
        const raw = fs.readFileSync(path.join(ROOT, "public-urls.env"), "utf8");
        for (const line of raw.split(/\r?\n/)) {
            const match = line.match(/^([A-Z0-9_]+)=(.*)$/);
            if (match) values[match[1]] = match[2].trim();
        }
    } catch {
        // Not running from the deployment tree.
    }
    return values;
}

const PUBLIC_URLS = readPublicUrls();

function parseArgs(argv) {
    const options = {
        count: null,
        api: process.env.NULLCORD_API_URL || PUBLIC_URLS.API_URL || "http://127.0.0.1:14702",
        invite: process.env.NULLCORD_INVITE || PUBLIC_URLS.DISCOVER_INVITE || "canyonlake",
        model: process.env.SEED_MODEL || "qwen2.5:3b",
        ollama: process.env.OLLAMA_HOST || "http://127.0.0.1:11434",
        concurrency: 2,
        confirm: false,
        dryRun: false,
        noAi: false,
        resetMemory: false,
        preview: 20,
        help: false,
        verbose: false,
        delay: 150,
    };
    for (let i = 0; i < argv.length; i += 1) {
        const arg = argv[i];
        const equals = arg.indexOf("=");
        const key = equals >= 0 ? arg.slice(0, equals) : arg;
        const inline = equals >= 0 ? arg.slice(equals + 1) : undefined;
        const next = () => inline ?? argv[(i += 1)];
        switch (key) {
            case "--count":
            case "-n":
                options.count = Number(next());
                break;
            case "--api":
                options.api = next();
                break;
            case "--invite":
                options.invite = next();
                break;
            case "--model":
                options.model = next();
                break;
            case "--ollama":
                options.ollama = next().replace(/\/+$/, "");
                break;
            case "--concurrency":
                options.concurrency = Math.max(1, Math.min(8, Number(next()) || 2));
                break;
            case "--delay":
                options.delay = Math.max(0, Number(next()) || 0);
                break;
            case "--confirm":
                options.confirm = true;
                break;
            case "--dry-run":
                options.dryRun = true;
                break;
            case "--no-ai":
                options.noAi = true;
                break;
            case "--reset-memory":
                options.resetMemory = true;
                break;
            case "--preview":
                options.preview = Math.max(1, Math.min(100, Number(next()) || 20));
                break;
            case "--verbose":
                options.verbose = true;
                break;
            case "--help":
            case "-h":
                options.help = true;
                break;
            default:
                if (/^\d+$/.test(arg) && options.count === null) {
                    options.count = Number(arg);
                } else {
                    throw new Error(`unknown argument: ${arg}`);
                }
        }
    }
    options.api = options.api.replace(/\/+$/, "");
    options.ollama = options.ollama.replace(/\/+$/, "").replace(/\/\/0\.0\.0\.0/, "//127.0.0.1");
    return options;
}

function printHelp() {
    console.log(`NullCord account seeder

  node seed-accounts.mjs <count> [options]

Options:
  --count N          number of accounts (positional count also works)
  --api URL          API base URL (default: ${process.env.NULLCORD_API_URL || "http://127.0.0.1:14702"})
  --invite CODE      invite to join (default: canyonlake)
  --model NAME       Ollama model (default: qwen2.5:3b)
  --ollama URL       Ollama base URL (default: http://127.0.0.1:11434)
  --concurrency N    parallel account workers (default: 2, max: 8)
  --no-ai            skip Ollama and use the local style generator
  --reset-memory     clear learned style memory before generating
  --preview N        preview at most N handles in dry-run mode (default: 20)
  --dry-run          generate and print sample handles without creating accounts
  --confirm          actually create accounts (required)
  --verbose          print request details

Credentials are written to seed/accounts.jsonl with mode 0600.
Style memory is written to seed/username-memory.json.
`);
}

function appendJsonLine(file, value) {
    fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
    fs.appendFileSync(file, `${JSON.stringify(value)}\n`, { mode: 0o600 });
    try {
        fs.chmodSync(file, 0o600);
    } catch {
        // best effort
    }
}

async function onboard(api, token, username) {
    let candidate = username;
    for (let attempt = 0; attempt < 6; attempt += 1) {
        try {
            await api.generalSlot();
            const user = await api.request("/onboard/complete", {
                method: "POST",
                token,
                body: { username: candidate },
            });
            return user;
        } catch (error) {
            if (!(error instanceof ApiError) || ![400, 409].includes(error.status)) throw error;
            const type = String(error.type || "").toLowerCase();
            const body = JSON.stringify(error.body || "").toLowerCase();
            if (!type.includes("username") && !body.includes("username") && !body.includes("taken")) {
                throw error;
            }
            const fallback = normalizeUsername(localUsername());
            candidate = normalizeUsername(
                fallback || `${candidate.slice(0, 27)}${randInt(10, 99)}`,
            );
            if (!candidate) candidate = `user${randInt(10000, 99999)}`;
        }
    }
    throw new Error("could not find a free username after 6 attempts");
}

async function createOne(api, options, index, username) {
    if (!username) throw new Error("username generator returned nothing");
    const email = randomEmail(index);
    const password = randomPassword();
    const displayName = makeDisplayName(username);
    const bio = makeBio(username);
    const statusText = makeStatus(username);

    await api.authSlot();
    await api.request("/auth/account/create", {
        method: "POST",
        body: { email, password },
    });

    await api.authSlot();
    const login = await api.request("/auth/session/login", {
        method: "POST",
        body: { email, password, friendly_name: "NullCord Seed" },
    });
    if (!login?.token) throw new Error(`login did not return a token (${login?.result || "unknown"})`);

    const user = await onboard(api, login.token, username);
    const finalName = user?.username || username;

    let joined = false;
    let joinError = null;
    if (options.invite) {
        try {
            await api.generalSlot();
            await api.request(`/invites/${encodeURIComponent(options.invite)}`, {
                method: "POST",
                token: login.token,
            });
            joined = true;
        } catch (error) {
            joinError = error.message;
        }
    }

    try {
        await api.generalSlot();
        await api.request("/users/@me", {
            method: "PATCH",
            token: login.token,
            body: {
                display_name: displayName,
                status: { text: statusText },
                profile: { content: bio },
            },
        });
    } catch (error) {
        if (options.verbose) console.log(`[profile] ${finalName}: ${error.message}`);
    }

    return {
        index,
        email,
        password,
        userId: login.user_id,
        username: finalName,
        displayName,
        bio,
        joined,
        joinError,
        createdAt: new Date().toISOString(),
    };
}

async function main() {
    let options;
    try {
        options = parseArgs(process.argv.slice(2));
    } catch (error) {
        console.error(error.message);
        printHelp();
        process.exitCode = 1;
        return;
    }
    if (options.help) {
        printHelp();
        return;
    }
    if (!Number.isInteger(options.count) || options.count < 1) {
        printHelp();
        process.exitCode = 1;
        return;
    }
    if (options.count > 1000) {
        console.error("refusing to create more than 1000 accounts in one run");
        process.exitCode = 1;
        return;
    }

    fs.mkdirSync(SEED_DIR, { recursive: true, mode: 0o700 });
    if (options.resetMemory) {
        fs.rmSync(MEMORY_FILE, { force: true });
        console.log("[seed] cleared learned username memory");
    }
    const memory = new StyleMemory();
    const forge = new NameForge(options, memory);
    await forge.warmup();

    if (!options.confirm || options.dryRun) {
        const preview = await forge.generate(Math.min(options.count, options.preview));
        console.log(`\nPreview (${preview.length} of ${options.count}):`);
        for (const name of preview) {
            console.log(`  ${name.padEnd(24)} ${makeDisplayName(name)}`);
        }
        console.log(
            `\nNo accounts were created. Re-run with --confirm to create ${options.count} account(s) on ${options.api}.`,
        );
        if (options.invite) console.log(`They will join invite "${options.invite}".`);
        return;
    }

    const api = new Api(options.api);
    console.log(`[seed] API: ${options.api}`);
    console.log(`[seed] creating ${options.count} accounts, concurrency ${options.concurrency}`);
    console.log(`[seed] invite: ${options.invite || "(none)"} | model: ${forge.aiAvailable ? forge.model : "local fallback"}`);
    console.log(`[seed] credentials: ${ACCOUNTS_FILE}`);
    try {
        const health = await api.health();
        console.log(`[seed] connected to ${health.stoat || health.revolt || "server"}`);
    } catch (error) {
        console.error(`[seed] cannot reach API: ${error.message}`);
        process.exitCode = 1;
        return;
    }

    console.log(`[seed] generating ${options.count} usernames...`);
    const usernames = await forge.generate(options.count);
    console.log(`[seed] generated ${usernames.length} unique usernames`);

    let nextIndex = 0;
    let completed = 0;
    let joined = 0;
    let failed = 0;
    let stopping = false;
    const failures = [];

    process.on("SIGINT", () => {
        if (stopping) process.exit(130);
        stopping = true;
        console.log("\n[seed] stopping after in-flight accounts...");
    });

    const worker = async () => {
        while (!stopping) {
            const index = nextIndex;
            nextIndex += 1;
            if (index >= options.count) return;
            try {
                const record = await createOne(api, options, index, usernames[index]);
                appendJsonLine(ACCOUNTS_FILE, record);
                completed += 1;
                if (record.joined) joined += 1;
                console.log(
                    `[${completed}/${options.count}] ${record.username}${record.displayName ? ` (${record.displayName})` : ""}${record.joined ? ` -> joined ${options.invite}` : " -> join FAILED"}`,
                );
                if (record.joinError) console.log(`[join] ${record.username}: ${record.joinError}`);
            } catch (error) {
                failed += 1;
                const failure = {
                    index,
                    error: error.message,
                    at: new Date().toISOString(),
                };
                failures.push(failure);
                appendJsonLine(FAILURES_FILE, failure);
                console.error(`[error] account ${index + 1}: ${error.message}`);
            }
            if (options.delay) await sleep(options.delay);
        }
    };

    await Promise.all(Array.from({ length: options.concurrency }, () => worker()));

    console.log("\n[seed] done");
    console.log(`  created:  ${completed}`);
    console.log(`  joined:   ${joined}`);
    console.log(`  failed:   ${failed}`);
    console.log(`  accounts: ${ACCOUNTS_FILE}`);
    console.log(`  memory:   ${MEMORY_FILE}`);
    if (failures.length) {
        console.log(`  failures: ${FAILURES_FILE}`);
        process.exitCode = 1;
    }
}

main().catch((error) => {
    console.error(`[seed] fatal: ${error.stack || error.message}`);
    process.exitCode = 1;
});
